constexpr HRESULT S_OK=0, E_FAIL=-1, E_INVALIDARG=-2, E_OUTOFMEMORY=-3, DXGI_ERROR_DEVICE_REMOVED=-4;
#define FAILED(hr) ((hr)<0)
#define CHECK(x) do { if(!(x)){std::fprintf(stderr,"FAIL teardown line=%d check=%s\n",__LINE__,#x);std::fflush(stderr);std::abort();} }while(0)
struct Device;
struct Query;
struct InputLayout;
struct Counters {
  unsigned made=0, released=0, premature=0, retired=0, drained=0, children=0;
  unsigned devices=0, gpu_closed=0, memory_closed=0, service_closed=0, reentered=0;
  bool exiting=false, check_exit=false;
};
static Counters counters;
static std::vector<std::weak_ptr<Device>> devices;
static const char* testCase;
static std::function<void()> releaseHook;
static void checkExit();
struct ExitCheck { ~ExitCheck(){checkExit();} } exitCheck;
// Destroy after the registry globals but before the final exit oracle.
static std::shared_ptr<Device> lateOwner;
namespace dxvk::umd {
struct RuntimeService {
  struct Retirement { Retirement* next=nullptr; virtual ~Retirement()=default; virtual void release()noexcept=0; };
  struct Scope {
    inline static thread_local RuntimeService* current=nullptr;
    RuntimeService* previous;
    explicit Scope(RuntimeService* p):previous(current){current=p;}
    ~Scope(){current=previous;}
  };
  RuntimeService(bool=false,bool=false){}
  bool closed=false;
  Retirement* retired=nullptr;
  void retire(Retirement* p)noexcept{CHECK(!closed);++counters.retired;p->next=retired;retired=p;}
  template<class F> void drain(F&& f){CHECK(!closed);++counters.drained;f();while(retired){auto p=retired;retired=p->next;p->release();delete p;}}
  void close(){CHECK(!closed&&!retired);closed=true;++counters.service_closed;}
  ~RuntimeService(){CHECK(!retired);}
};
}
struct IUnknown {
  IUnknown(){++counters.made;}
  virtual ~IUnknown(){
    ++counters.released;
    if(!dxvk::umd::RuntimeService::Scope::current)++counters.premature;
    if(releaseHook){auto f=std::move(releaseHook);releaseHook={};f();}
  }
};
struct ID3D11Query: IUnknown{};
struct ID3D11InputLayout: IUnknown{};
template<class T>struct ComPtr {
  T* p=nullptr;
  ComPtr()=default;ComPtr(const ComPtr&)=delete;ComPtr& operator=(const ComPtr&)=delete;
  ComPtr(ComPtr&& o)noexcept:p(std::exchange(o.p,nullptr)){}
  ~ComPtr(){Reset();}
  void Attach(T* x){CHECK(!p);p=x;}
  T* Detach(){return std::exchange(p,nullptr);}
  void Reset(){delete std::exchange(p,nullptr);}
};
struct Gpu {HRESULT close(){++counters.gpu_closed;return S_OK;}};
struct Memory {HRESULT closeDeviceAllocations(){++counters.memory_closed;return S_OK;}};
void clearRegisteredChildren(Device*)noexcept;
struct Device {
  explicit Device(bool disableExtraThreads=false):service(std::make_shared<dxvk::umd::RuntimeService>(false,disableExtraThreads)){++counters.devices;}
  std::shared_ptr<dxvk::umd::RuntimeService> service;
  std::shared_ptr<Gpu> gpu=std::make_shared<Gpu>();
  Memory memory;
  struct Bindings {std::vector<void*> pointers;std::vector<std::unique_ptr<int>> owners;};
  std::array<Bindings,6> classBindings;
  std::shared_ptr<InputLayout> inputLayout;
  ComPtr<IUnknown> rotationScratch,predicate,context,backend;
  bool closing=false;
  std::atomic<bool> retired{false};
#include "device_close.inc"
};
